{
  "interpretation": {
    "name": "TightenForkliftFastenersLine1WithNR7",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten the fasteners of variant F25 at station st1 on line 1 with tool NR7, evaluate and record the result, then return NR7 to the crib.",
    "constraints": [
      "Reserve NR7 exclusively before any use and release it only after it is back at the crib",
      "NR7 must be at station st1 before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program and no numeric process values appear in the Recipe",
      "Every tightening is evaluated against its program and recorded for traceability",
      "transport-tool Steps are delegated to agvexecutor",
      "Every tool-using Step renews the lease and therefore depends on reserve-tool"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, immediate",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-line1-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "evaluate-and-record",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten-bolts"], "dep": ["program", "reserve"], "executor": null, "params": {}},
          {"name": "tighten-bolts", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "evaluate-and-record",
        "next": "return-tool",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten-bolts", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten-bolts"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
